export function view(
  s: State,
  id: string,
  mode: string,
  code?: string,
  now = Date.now(),
): View {
  const v: View = { now, me: id };
  if (mode === "solo") {
    const r = soloRun(s, id, code || "FREE", now);
    if (r) {
      const c = r.current;
      v.solo = {
        id: r.id,
        mode: r.mode,
        ends: r.ends,
        finished: r.finished,
        score: r.score,
        solved: r.solved,
        streak: r.streak,
        best: r.best,
        position: r.position,
        stage: Math.min(5, c.guesses.length + 1),
        guesses: c.guesses.map(({ text, stage, correct }) => ({
          text,
          stage,
          correct,
        })),
        done: c.done,
        correct: c.solved,
        points: c.points,
        category: puzzleById(c.puzzle).category,
        repeat: false,
        ...(c.done || r.finished
          ? { answer: puzzleById(c.puzzle).answer, credit: creditFor(c.puzzle) }
          : {}),
      };
    }
  }
  if (mode === "daily") {
    const r = dailyRun(s, id, now);
    v.daily = {
      number: r.day - dailyAt(Date.UTC(2026, 0, 1)) + 1,
      ends: (r.day + 1) * 86400000,
      stage: Math.min(5, r.guesses.length + 1),
      guesses: r.guesses.map(({ text, stage, correct }) => ({
        text,
        stage,
        correct,
      })),
      done: r.done,
      solved: r.solved,
      ...(r.done
        ? { answer: puzzleById(r.puzzle).answer, credit: creditFor(r.puzzle) }
        : {}),
    };
  }
  if (mode === "room") {
    const r = getRoom(s, code || "", now);
    if (!r.members.some((m) => m.id === id)) fail("Join this room first");
    advance(r, now);
    const d = r.roundData;
    const reveal = !!d?.revealAt || r.status === "finished";
    const sanitize = (g: Round["guesses"][number], author: boolean) => ({
      text: g.text,
      stage: g.stage,
      correct: g.correct,
      ...(author
        ? {
            player: g.player,
            author: g.player ? s.players[g.player]?.name : undefined,
          }
        : {}),
    });
    v.room = {
      code: r.code,
      host: r.host,
      status: r.status,
      members: r.members.map((m) => ({
        ...m,
        connected: now - m.seen < 45000,
      })),
      rounds: r.rounds,
      duration: r.duration,
      category: r.category,
      round: r.round,
      starts: d?.starts,
      ends: d?.ends,
      revealAt: d?.revealAt,
      stage: d ? stageAt(d.starts, r.duration, now) : 1,
      ...(reveal && d
        ? { answer: puzzleById(d.puzzle).answer, credit: creditFor(d.puzzle) }
        : {}),
      feed: (d?.guesses || [])
        .filter((g) => reveal || !g.correct)
        .slice(-16)
        .map((g) => sanitize(g, reveal)),
      myGuesses: (d?.guesses || [])
        .filter((g) => g.player === id)
        .map((g) => sanitize(g, true)),
      solved: d?.solved || {},
      repeat: r.repeat,
    };
  }
  return v;
}
export function authorizedImage(
  s: State,
  id: string,
  mode: string,
  code?: string,
  now = Date.now(),
) {
  if (mode === "solo") {
    const r = soloRun(s, id, code || "FREE", now);
    if (!r) fail("Picture not available");
    return `${r.current.puzzle}-${r.current.done || r.finished ? 6 : Math.min(5, r.current.guesses.length + 1)}.webp`;
  }
  if (mode === "daily") {
    const r = dailyRun(s, id, now);
    return `${r.puzzle}-${r.done ? 6 : Math.min(5, r.guesses.length + 1)}.webp`;
  }
  const r = getRoom(s, code || "", now);
  if (!r.members.some((m) => m.id === id)) fail("Join this room first");
  advance(r, now);
  const d = r.roundData;
  if (!d || now < d.starts) fail("Picture not available");
  return `${d.puzzle}-${d.revealAt || r.status === "finished" ? 6 : stageAt(d.starts, r.duration, now)}.webp`;
}
